        requested: num,
        startSample,
        totalSamples,
        remaining: Math.max(0, totalSamples - startSample),
        renderedSamples: rendered ? rendered.length : 0,
        renderedSeconds: rendered ? rendered.length / SAMPLE_RATE : 0,
