        subPath,
        points,
        bounds,
        interiorPoint: getInteriorPoint(points, bounds),
        absArea: Math.abs(area),
        // ShapeUtils uses positive area for counter-clockwise contours.
        winding: area < 0 ? -1 : 1,
        container: null,
